// Requires the external nlohmann/json single-header library.
#include <iostream>
#include <nlohmann/json.hpp>
int main() {
    const auto config = nlohmann::json::parse(R"({"port": 8080, "debug": true})");
    const int port = config.at("port").get<int>();
    const bool debug = config.at("debug").get<bool>();
    std::cout << "port=" << port << ", debug=" << std::boolalpha << debug << '\n';
}
